      162:         tif->tif_rawcp += n;
      163:         tif->tif_rawcc += n;
      164:         pp += n;
      165:         cc -= (size_t)n;
      166:         if (tif->tif_rawcc >= tif->tif_rawdatasize && !TIFFFlushData1(tif))
      167:         {
      168:             return (-1);
      169:         }
      170:     }
      171: 
      172:     return (1);
      173: }
